"use client";

// ticker-404 · 404lab
// Requires ./chrome.tsx and the 404lab tokens.

import { useEffect, useRef, useState } from "react";
import { motion, useInView, useReducedMotion } from "motion/react";
import { Caption, Foot, Screen } from "./chrome";

/* ---------------------------------- ticker --------------------------------- */

const ALPHA = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
const TARGET = ["4", "0", "4"];

export function TickerDemo() {
  const reduce = useReducedMotion();
  const ref = useRef<HTMLDivElement>(null);
  const inView = useInView(ref, { once: true, margin: "-20px" });
  const [chars, setChars] = useState(TARGET);
  const [spin, setSpin] = useState(0);
  const busy = useRef(false);

  useEffect(() => {
    if (!inView) return;
    if (reduce) {
      setChars(TARGET);
      return;
    }
    busy.current = true;
    let n = 0;
    const id = setInterval(() => {
      n += 1;
      if (n > 9) {
        clearInterval(id);
        setChars(TARGET);
        busy.current = false;
        return;
      }
      setChars(
        TARGET.map(() => ALPHA[Math.floor(Math.random() * ALPHA.length)]),
      );
    }, 92);
    return () => clearInterval(id);
  }, [inView, spin, reduce]);

  function replay() {
    if (reduce || busy.current) return;
    setSpin((s) => s + 1);
  }

  return (
    <Screen ref={ref} onPointerEnter={replay} onClick={replay} className="bg-[#07080a]">
      <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_center,rgba(242,237,227,0.05),transparent_65%)]" />

      <div className="absolute inset-0 flex flex-col items-center justify-center gap-3 px-5">
        <div className="flex w-full max-w-[280px] items-center justify-between lab-mono text-[9px] text-white/40">
          <span>departures</span>
          <span>04:04</span>
        </div>

        <div className="flex items-start gap-2">
          {chars.map((c, i) => (
            <div
              key={i}
              className="relative grid h-[84px] w-[60px] place-items-center overflow-hidden rounded-[3px] border border-line-2 bg-ink-850 [perspective:260px]"
            >
              <motion.span
                key={`${c}-${i}`}
                initial={reduce ? false : { rotateX: -86, opacity: 0 }}
                animate={{ rotateX: 0, opacity: 1 }}
                transition={{ duration: 0.18, ease: "easeOut" }}
                className="display text-[52px] leading-none text-fg"
              >
                {c}
              </motion.span>
              <span className="absolute inset-x-0 top-1/2 h-px bg-ink-950" />
              <span className="absolute left-[3px] top-1/2 size-1 -translate-y-1/2 rounded-full bg-ink-950" />
              <span className="absolute right-[3px] top-1/2 size-1 -translate-y-1/2 rounded-full bg-ink-950" />
              <span className="pointer-events-none absolute inset-x-0 top-0 h-1/2 bg-[linear-gradient(180deg,rgba(255,255,255,0.06),transparent)]" />
            </div>
          ))}
        </div>

        <div className="mt-1 flex w-full max-w-[280px] flex-col gap-1.5 lab-mono text-[9px] text-white/40">
          <span className="flex items-baseline gap-2">
            <span className="text-white/60">nowhere</span>
            <span className="h-px flex-1 bg-[repeating-linear-gradient(to_right,rgba(242,237,227,0.18)_0_2px,transparent_2px_6px)]" />
            <span className="text-amber/70">on time</span>
          </span>
          <span className="flex items-baseline gap-2">
            <span className="text-white/60">gate 404</span>
            <span className="h-px flex-1 bg-[repeating-linear-gradient(to_right,rgba(242,237,227,0.18)_0_2px,transparent_2px_6px)]" />
            <span>boarding</span>
          </span>
        </div>
      </div>

      <Caption label="404 / ticker" />
      <Foot method="split-flap · 92ms" />
    </Screen>
  );
}

"use client";

import Image from "next/image";
import { motion, useReducedMotion } from "motion/react";
import { useState } from "react";
import { ArrowUpRight, Check, Copy } from "lucide-react";

export const EASE = [0.22, 1, 0.36, 1] as const;

/* Every card shares the same framing so the grid reads as one set. */

export function Caption({
  label,
  className = "",
}: {
  label: string;
  className?: string;
}) {
  return (
    <span
      className={`pointer-events-none absolute left-4 top-3 z-20 lab-mono text-[10px] tracking-[0.02em] text-white/75 [text-shadow:0_1px_3px_rgba(8,9,10,0.6)] ${className}`}
    >
      {label}
    </span>
  );
}

export function HomeLink({ label = "back home" }: { label?: string }) {
  return (
    <span className="pointer-events-none inline-flex items-center gap-1 lab-mono text-[10px] text-white/70">
      {label}
      <ArrowUpRight className="size-3" strokeWidth={1.5} />
    </span>
  );
}

export function Foot({
  method,
  label,
}: {
  method: string;
  label?: string;
}) {
  return (
    <div className="pointer-events-none absolute inset-x-0 bottom-0 z-20 flex items-center justify-between px-4 pb-3">
      <HomeLink label={label} />
      <span className="lab-mono text-[10px] text-white/50">{method}</span>
    </div>
  );
}

const SCREEN =
  "group @container relative h-full w-full overflow-hidden bg-ink-900";

export function Screen({
  className = "",
  children,
  ...rest
}: React.ComponentProps<"div">) {
  return (
    <div {...rest} className={`${SCREEN} ${className}`}>
      {children}
    </div>
  );
}

export function ScreenButton({
  className = "",
  children,
  ...rest
}: React.ComponentProps<"button">) {
  return (
    <button
      type="button"
      {...rest}
      className={`${SCREEN} cursor-default text-left ${className}`}
    >
      {children}
    </button>
  );
}

export function Plate({
  src,
  className = "",
  sizes = "(max-width: 768px) 100vw, 33vw",
  opacity,
  position = "center",
}: {
  src: string;
  className?: string;
  sizes?: string;
  opacity?: number;
  position?: string;
}) {
  return (
    <Image
      src={src}
      alt=""
      fill
      sizes={sizes}
      className={`object-cover ${className}`}
      style={{ opacity, objectPosition: position }}
    />
  );
}

/* --------------------------------- helpers -------------------------------- */

export function useReplay() {
  const [run, setRun] = useState(0);
  return { run, replay: () => setRun((n) => n + 1) };
}

export function useStill() {
  return useReducedMotion() ?? false;
}

export const clamp = (v: number, min: number, max: number) =>
  Math.max(min, Math.min(max, v));

/* ------------------------------- install bits ------------------------------ */

export function CopyCommand({
  command,
  className = "",
}: {
  command: string;
  className?: string;
}) {
  const [done, setDone] = useState(false);

  async function copy() {
    try {
      await navigator.clipboard.writeText(command);
      setDone(true);
      setTimeout(() => setDone(false), 1600);
    } catch {
      setDone(false);
    }
  }

  return (
    <button
      type="button"
      onClick={copy}
      aria-label={`Copy ${command}`}
      className={`group/copy flex w-full items-center justify-between gap-4 rounded-control border border-line bg-ink-900 px-3 py-2.5 text-left transition-colors duration-200 hover:border-line-2 active:translate-y-px ${className}`}
    >
      <code className="min-w-0 break-all lab-mono text-[10px] text-fg-2 sm:truncate lg:text-[12px]">
        <span className="mr-1.5 text-amber/80">$</span>
        {command}
      </code>
      <span className="shrink-0 text-fg-3 transition-colors duration-200 group-hover/copy:text-fg">
        {done ? (
          <Check className="size-4" strokeWidth={1.5} />
        ) : (
          <Copy className="size-4" strokeWidth={1.5} />
        )}
      </span>
    </button>
  );
}

export function Reveal({
  children,
  delay = 0,
  className = "",
}: {
  children: React.ReactNode;
  delay?: number;
  className?: string;
}) {
  const reduce = useReducedMotion();
  return (
    <motion.div
      className={className}
      initial={reduce ? false : { opacity: 0, y: 10 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true, margin: "-60px" }}
      transition={{ duration: 0.55, ease: EASE, delay }}
    >
      {children}
    </motion.div>
  );
}
